select.if:
SELECT distinct b.process_id id,c.`name`,c.product_type,c.sort FROM mes_building_team_user_link a LEFT JOIN mes_building_team b ON a.team_id=b.id AND b.bool_delete_enum=FALSE LEFT JOIN mes_building_process c ON b.process_id=c.id and c.bool_delete_enum=FALSE WHERE a.bool_delete_enum=FALSE AND c.production_line_type_enum = 1 AND a.user_id=#{userId}
AND c.product_type &#{taskTypeEnum}
order by c.sort ASC

SELECT distinct b.process_id id,c.`name`,c.product_type,c.sort FROM mes_building_inspection_team_user_link a LEFT JOIN mes_building_inspection_team b ON a.inspection_team_id=b.id AND b.bool_delete_enum=FALSE LEFT JOIN mes_building_process c ON b.process_id=c.id AND c.bool_delete_enum=FALSE WHERE a.bool_delete_enum=FALSE AND c.production_line_type_enum = 1 AND a.user_id=#{userId}
AND c.product_type &#{taskTypeEnum}
order by c.sort ASC

SELECT distinct b.process_id id,c.`name`,c.product_type,c.sort,c.report_type,c.inspect_type FROM mes_building_team_user_link a LEFT JOIN mes_building_team b ON a.team_id=b.id AND b.bool_delete_enum=FALSE LEFT JOIN mes_building_process c ON b.process_id=c.id and c.bool_delete_enum=FALSE WHERE a.bool_delete_enum=FALSE AND c.production_line_type_enum = 1 AND a.user_id=#{userId}
AND c.product_type &#{taskTypeEnum}
order by c.product_type,c.sort,c.`name` ASC

SELECT distinct a.process_id id,c.`name`,c.product_type,c.sort FROM mes_inspect_config a LEFT JOIN mes_building_process c ON a.process_id=c.id and c.bool_delete_enum=FALSE Left join mes_inspect_config_user_link b ON a.id=b.inspect_config_id AND b.bool_delete_enum=FALSE AND b.bool_delete_enum=FALSE WHERE a.bool_delete_enum=FALSE AND c.production_line_type_enum = 1 AND b.inspect_user_id=#{userId}
AND c.product_type &#{taskTypeEnum}
and a.status = 1 order by c.product_type,c.sort,c.`name` ASC

mapper.select:
SELECT DISTINCT b.id, b.`name` FROM mes_building_team a LEFT JOIN mes_building_process b ON a.process_id = b.id
a.bool_delete_enum = FALSE
AND a.production_line_id =#{productionLineId}
AND b.product_type =#{productType}

SELECT a.id, COUNT(distinct detail.number) AS quantity, a.STATUS, a.technology_status, a.task_type_enum, a.ask_complete_time, a.product_id, a.sequence, a.project_id 'project.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', a.monomer_id 'monomer.id', pm.`name` 'monomer.name', a.area_id 'area.id', pd.`name` 'area.name', a.process_id 'process.id', mbp.name 'process.name', workshop.id 'workshop.id', workshop.`name` 'workshop.name', production_line.id 'production_line.id', production_line.`name` 'production_line.name', aproduction_line.id 'assistProductionLine.id', aproduction_line.`name` 'assistProductionLine.name', gro.id 'group.id', gro.name 'group.name', agroups.id 'assistGroup.id', agroups.name 'assistGroup.name', case a.sequence when 0 THEN 1 else 0 end bool_first_process, mbp.report_type report_type, mba.serial_number serial_number FROM mes_building_assist assist LEFT JOIN mes_building_task_process a ON assist.task_process_id=a.id AND a.bool_delete_enum=FALSE AND a.task_type_enum&#{taskTypeEnum} LEFT JOIN mes_building_assist_number_detail detail on detail.task_process_id = a.id and detail.bool_delete_enum =0 and detail.bool_finish_enum =0
INNER JOIN mes_building_task_number_link link ON link.artifact_task_process_id = detail.task_process_id and link.bool_artifact_report = false and link.bool_delete_enum = 0 and link.artifact_number = detail.number
INNER JOIN mes_building_task_number_link link ON link.assemble_task_process_id = detail.task_process_id and link.bool_assemble_report = false and link.bool_delete_enum = 0 and link.assemble_number = detail.number
LEFT JOIN contract_project cp ON cp.id =a.project_id AND cp.bool_delete_enum=FALSE LEFT JOIN mes_building_task_order task_order on task_order.id=a.task_order_id LEFT JOIN plan_monomer pm ON pm.id =a.monomer_id AND pm.bool_delete_enum=FALSE LEFT JOIN plan_area pd ON pd.id =a.area_id AND pd.bool_delete_enum=FALSE LEFT JOIN mes_building_process mbp on mbp.id=a.process_id AND mbp.bool_delete_enum=FALSE LEFT JOIN mes_building_workshop workshop ON a.workshop_id = workshop.id LEFT JOIN mes_building_production_line production_line ON a.production_line_id=production_line.id LEFT JOIN mes_building_groups gro ON a.groups_id=gro.id LEFT JOIN mes_building_groups agroups ON assist.groups_id=agroups.id LEFT JOIN mes_building_production_line aproduction_line ON agroups.production_line_id=aproduction_line.id
LEFT JOIN tech_artifact mba ON a.product_id =mba.id
LEFT JOIN tech_enclosure mba ON a.product_id =mba.id
LEFT JOIN tech_assemble mba ON a.product_id =mba.id
LEFT JOIN tech_machine_part mba ON a.product_id =mba.id
assist.id in
#{id}
and detail.assist_id in
#{id}
AND assist.bool_finish_enum=0
AND a.project_id =#{projectId}
AND a.monomer_id =#{monomerId}
AND a.area_id =#{areaId}
AND a.area_batch_id =#{areaBatchId}
AND a.task_id =#{taskId}
AND mba.serial_number like concat('%',#{serialNumber},'%')
GROUP BY a.id, a.task_type_enum, a.product_id, a.project_id, a.monomer_id, a.area_id, a.process_id, workshop.id, production_line.id, aproduction_line.id, gro.id, agroups.id ORDER BY mba.serial_number,a.ask_complete_time,a.id

SELECT a.id, COUNT(distinct detail.number) AS quantity, a.STATUS, a.technology_status, a.task_type_enum, a.ask_complete_time, a.product_id, a.sequence, a.project_id 'project.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', a.monomer_id 'monomer.id', pm.`name` 'monomer.name', a.area_id 'area.id', pd.`name` 'area.name', a.process_id 'process.id', mbp.name 'process.name', workshop.id 'workshop.id', workshop.`name` 'workshop.name', production_line.id 'production_line.id', production_line.`name` 'production_line.name', aproduction_line.id 'assistProductionLine.id', aproduction_line.`name` 'assistProductionLine.name', case a.sequence when 0 THEN 1 else 0 end bool_first_process, mbp.report_type report_type, mba.serial_number serial_number FROM mes_building_assist assist LEFT JOIN mes_building_task_process a ON assist.task_process_id=a.id AND a.bool_delete_enum=FALSE AND a.task_type_enum&#{taskTypeEnum} LEFT JOIN mes_building_assist_number_detail detail on detail.task_process_id = a.id and detail.bool_delete_enum =0 and detail.bool_finish_enum =0
INNER JOIN mes_building_task_number_link link ON link.artifact_task_process_id = detail.task_process_id and link.bool_artifact_report = false and link.bool_delete_enum = 0 and link.artifact_number = detail.number
INNER JOIN mes_building_task_number_link link ON link.assemble_task_process_id = detail.task_process_id and link.bool_assemble_report = false and link.bool_delete_enum = 0 and link.assemble_number = detail.number
LEFT JOIN contract_project cp ON cp.id =a.project_id AND cp.bool_delete_enum=FALSE LEFT JOIN mes_building_task_order task_order on task_order.id=a.task_order_id LEFT JOIN plan_monomer pm ON pm.id =a.monomer_id AND pm.bool_delete_enum=FALSE LEFT JOIN plan_area pd ON pd.id =a.area_id AND pd.bool_delete_enum=FALSE LEFT JOIN mes_building_process mbp on mbp.id=a.process_id AND mbp.bool_delete_enum=FALSE LEFT JOIN mes_building_workshop workshop ON a.workshop_id = workshop.id LEFT JOIN mes_building_production_line production_line ON a.production_line_id=production_line.id LEFT JOIN mes_building_production_line aproduction_line ON detail.production_line_id=aproduction_line.id
LEFT JOIN tech_artifact mba ON a.product_id =mba.id
LEFT JOIN tech_enclosure mba ON a.product_id =mba.id
LEFT JOIN tech_assemble mba ON a.product_id =mba.id
LEFT JOIN tech_machine_part mba ON a.product_id =mba.id
assist.id in
#{id}
and detail.assist_id in
#{id}
AND assist.bool_finish_enum=0
AND a.project_id =#{projectId}
AND a.monomer_id =#{monomerId}
AND a.area_id =#{areaId}
AND a.area_batch_id =#{areaBatchId}
and a.process_id = #{processId}
AND a.task_id =#{taskId}
AND mba.serial_number like concat('%',#{serialNumber},'%')
GROUP BY a.id, a.task_type_enum, a.product_id, a.project_id, a.monomer_id, a.area_id, a.process_id, workshop.id, production_line.id, aproduction_line.id ORDER BY mba.serial_number,a.ask_complete_time,a.id
